window.SyntaxHighlighter = (function() {
  const javaKeywords = new Set([
    'abstract','assert','boolean','break','byte','case','catch','char','class','const','continue',
    'default','do','double','else','enum','extends','final','finally','float','for','goto','if',
    'implements','import','instanceof','int','interface','long','native','new','package','private',
    'protected','public','return','short','static','strictfp','super','switch','synchronized','this',
    'throw','throws','transient','try','void','volatile','while','record','sealed','permits','non-sealed','var','yield'
  ]);

  const pythonKeywords = new Set([
    'and','as','assert','async','await','break','class','continue','def','del','elif','else','except',
    'finally','for','from','global','if','import','in','is','lambda','nonlocal','not','or','pass',
    'raise','return','try','while','with','yield','True','False','None','match','case'
  ]);

  function escapeHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function highlight(code, lang) {
    const language = (lang || "").toLowerCase();
    const lines = code.split('\n');
    const keywords = language === 'python' ? pythonKeywords : javaKeywords;

    // Token regex matches left-to-right in single pass without placeholders.
    // 1: String ("..." or '...' or """...""" or '''...''')
    // 2: Comment (#... or //... or /*...*/)
    // 3: Annotation (@Word)
    // 4: Number (\b\d+(\.\d+)?\b)
    // 5: Identifier (\b[a-zA-Z_]\w*\b)
    // 6: Other characters
    const pyRegex = /("""[\s\S]*?"""|'''[\s\S]*?'''|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|(#.*$)|(@[a-zA-Z_]\w*)|\b(\d+(?:\.\d+)?)\b|\b([a-zA-Z_]\w*)\b|([\s\S])/g;
    const javaRegex = /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')|(\/\/.*$|\/\*[\s\S]*?\*\/)|(@[a-zA-Z_]\w*)|\b(\d+(?:\.\d+)?)\b|\b([a-zA-Z_]\w*)\b|([\s\S])/g;

    const regex = language === 'python' ? pyRegex : javaRegex;

    const highlightedLines = lines.map(line => {
      regex.lastIndex = 0;
      return line.replace(regex, (match, str, comment, ann, num, ident, other) => {
        if (str !== undefined) {
          return '<span class="hl-string">' + escapeHtml(str) + '</span>';
        }
        if (comment !== undefined) {
          return '<span class="hl-comment">' + escapeHtml(comment) + '</span>';
        }
        if (ann !== undefined) {
          return '<span class="hl-annotation">' + escapeHtml(ann) + '</span>';
        }
        if (num !== undefined) {
          return '<span class="hl-number">' + escapeHtml(num) + '</span>';
        }
        if (ident !== undefined) {
          if (keywords.has(ident)) {
            return '<span class="hl-keyword">' + escapeHtml(ident) + '</span>';
          }
          if (/^[A-Z][a-zA-Z0-9_]*$/.test(ident)) {
            return '<span class="hl-type">' + escapeHtml(ident) + '</span>';
          }
          return escapeHtml(ident);
        }
        return escapeHtml(other);
      });
    });

    return highlightedLines.join('\n');
  }

  return { highlight: highlight, escapeHtml: escapeHtml };
})();